{
  "items": [
    {
      "label": "FIGURE 2.12",
      "kind": "chart",
      "title": "The reduction in inequality has been faster for economies with high levels of initial inequality",
      "bbox": [
        83,
        163,
        500,
        825
      ],
      "content": {
        "chart_type": "scatter plot",
        "x_axis": {
          "title": "Initial Gini index",
          "range": [20, 70]
        },
        "y_axis": {
          "title": "Annualized change in Gini index 2000–22 (%)",
          "range": [-2.0, 1.5]
        },
        "legend": [
          "Economies using consumption data",
          "Economies using income data",
          "Fitted line, consumption",
          "Fitted line, income"
        ],
        "description": "The chart shows a negative correlation between the initial Gini index and the annualized change in the Gini index. Economies with higher initial Gini indices tend to have a more negative annualized change (faster reduction in inequality). The fitted lines for both consumption and income data show a downward trend.",
        "sources": "World Bank, Poverty and Inequality Platform (version September 2024), https://pip.worldbank.org; Haddad et al. 2024 (updated).",
        "notes": "Initial Gini index for each economy is for the earliest available year, starting with 2000. The vertical axis shows the (annualized) percent change between the initial Gini and its final value, obtained from the latest survey round. The sample consists of 155 economies with at least two surveys. There might be breaks in comparability over such a long period, which are not controlled for."
      }
    }
  ]
}
